<h3>Origine</h3><dl class="detail-sheet__grid"><?=$fact('Étang · parcelle',$h['pond_name'].' · '.$h['parcel_code'],$h['parcel_name'])?><?=$fact('Lot',$h['batch_number'],$h['species_name'])?><?=$fact('Pêche',$stamp($h['caught_at']),$h['site_name'])?><?=$fact('Poissons comptés',$int($h['heads_caught']),'Survivants pêchés')?></dl>
<h3>Pesée à la ferme</h3><dl class="detail-sheet__grid"><?=$fact('Poids net',$kg($h['net_weight_kg']).' kg')?><?php if((float)$h['tare_weight_kg']>0): ?><?=$fact('Poids brut',$kg($h['gross_weight_kg']).' kg')?><?=$fact('Tare',$kg($h['tare_weight_kg']).' kg',(string)$h['tare_note'])?><?php else: ?><?=$fact('Mode de pesée','Poids net','Sans contenant')?><?php endif; ?><?=$fact('Rendement',(float)$h['yield_kg_m2']>0?number_format((float)$h['yield_kg_m2'],3,',',' ').' kg/m²':'—')?></dl>
<h3>Suivi</h3><dl class="detail-sheet__grid"><?=$fact('DLC',date('d/m/Y',strtotime($h['expiry_date'])))?><?=$fact('Saisie par',$h['author']?:'—',date('d/m/Y H:i',strtotime($h['created_at'])))?><?=$fact('Validée par',$h['validator']?:'—',$h['validated_at']?date('d/m/Y H:i',strtotime($h['validated_at'])):'')?><?php if($h['status']==='validated'&&$h['weight_stock_id']): ?><?=$fact('Stock pesé',$kg($h['stock_kg']).' kg',$availableKg>0?$kg($availableKg).' kg à envoyer':'Entièrement envoyé')?><?php endif; ?></dl>
