elseif($h['status']==='validated'&&$availableKg>0&&$h['expiry_date']>=date('Y-m-d')&&Auth::can('livestock','create',$site)): ?><button type="button" class="btn-primary" data-workspace-modal-open="fish-shipment" data-fish-stock="<?=e($h['weight_stock_id'])?>"><i class="bi bi-truck" aria-hidden="true"></i> Préparer un envoi</button><?php endif; ?>
</footer>
<?php require $flowViews.'/drawer_end.php'; ?>
