</div>
<footer><button type="button" class="btn-secondary" data-workspace-modal-close>Fermer</button><button type="button" class="btn-secondary" data-workspace-modal-open="btr-preview" data-btr-url="<?=e(base_url('livestock/fish/shipments/'.$t['id'].'/btr'))?>" data-btr-title="<?=e($t['transfer_number'])?>" data-workspace-return-focus="fish-shipment-menu-<?=e($t['id'])?>-toggle"><i class="bi bi-file-earmark-text" aria-hidden="true"></i> Bon de transfert</button>
<?php if($t['status']==='draft'&&Auth::can('livestock','validate',$site)):$rowAction='livestock/fish/shipments/'.$t['id'].'/approve';$rowConfirm='Approuver cet envoi et réserver le poisson ?';$rowLabel='Approuver';$rowIcon='bi-check2-circle';require dirname(__DIR__).'/partials/row_form.php';
elseif($t['status']==='approved'&&Auth::can('livestock','update',$site)):$rowAction='livestock/fish/shipments/'.$t['id'].'/dispatch';$rowConfirm='Confirmer le départ du poisson vers la boucherie ?';$rowLabel='Expédier';$rowIcon='bi-truck';require dirname(__DIR__).'/partials/row_form.php';endif; ?>
